program_code = '''from copy import deepcopy

def transform(grid):
    rows, cols = len(grid), len(grid[0])

    sep_row = None
    for r in range(1, rows - 1):
        c0 = grid[r][0]
        if c0 != 0 and all(grid[r][c] == c0 for c in range(cols)):
            sep_row = r
            break

    if sep_row is None:
        return grid

    colored_cells = []
    for r in range(rows):
        if r == sep_row:
            continue
        for c in range(cols):
            if grid[r][c] != 0:
                colored_cells.append((r, c))

    top_cells = [c for c in colored_cells if c[0] < sep_row]
    bot_cells = [c for c in colored_cells if c[0] > sep_row]

    if not top_cells or not bot_cells:
        return grid

    top_cols = set(c for r, c in top_cells)
    bot_cols = set(c for r, c in bot_cells)

    fill_cols = list(sorted(top_cols & bot_cols))

    if len(top_cols) > len(bot_cols):
        fill_start_row = 1
        fill_end_row = sep_row - 1
    else:
        fill_start_row = sep_row + 1
        fill_end_row = min(r for r, c in bot_cells) - 1

    result = deepcopy(grid)
    for r in range(fill_start_row, fill_end_row + 1):
        for c in fill_cols:
            result[r][c] = 4

    return result
'''

